{
  "results": [
    {
      "server": "pencil",
      "tools": [
        {
          "tool_name": "pencil__export_nodes",
          "description": "Export nodes to image files in PNG/JPEG/WEBP/PDF formats.\n\n- Takes an array of node IDs and exports each one as a separate image file.\n- Supports PNG, JPEG, WEBP and PDF formats.\n- Writes files to the specified output directory using node IDs as filenames.\n- Returns the absolute paths of the created files.\n- Uses 2x scale and 8192 max resolution for high-quality exports.\n- For PDF, all nodes are combined into a single multi-page document.",
          "score": 4.752348899841309,
          "input_schema": {
            "properties": {
              "filePath": {
                "description": "An optional file path to access a .pen file.",
                "type": "string"
              },
              "format": {
                "description": "Export format (default: png)",
                "enum": [
                  "png",
                  "jpeg",
                  "webp",
                  "pdf"
                ],
                "type": "string"
              },
              "nodeIds": {
                "description": "Array of node IDs to export",
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              "outputDir": {
                "description": "Directory to write exported files to",
                "type": "string"
              },
              "quality": {
                "description": "Export quality for JPEG and WEBP (1-100). Defaults to 95 for JPEG, 100 (lossless) for WEBP.",
                "type": "number"
              },
              "scale": {
                "description": "Export scale factor (default: 2). Not applicable to PDF.",
                "type": "number"
              }
            },
            "required": [
              "filePath",
              "outputDir",
              "nodeIds"
            ],
            "type": "object"
          }
        },
        {
          "tool_name": "pencil__get_variables",
          "description": "Get the variables and themes defined in this .pen file.\n\n- Use the result of this tool to create global CSS rules to use in a codebase.\n- When generating code from a design, use this tool to get the global styling rules associated with the design.",
          "score": 3.277777671813965,
          "input_schema": {
            "properties": {
              "filePath": {
                "description": "An optional file path to access a .pen file.",
                "type": "string"
              }
            },
            "required": [
              "filePath"
            ],
            "type": "object"
          }
        },
        {
          "tool_name": "pencil__export_html",
          "description": "Export nodes to HTML.\n\n- Takes an array of node IDs and exports them as HTML.\n- Supports HTML + Tailwind and HTML + CSS output.\n- Can include a full HTML scaffold, layer names, and layer IDs.\n- Image assets are always referenced with relative paths (never embedded).\n- Writes the HTML file to outputPath and returns its absolute path.",
          "score": 2.9840939044952393,
          "input_schema": {
            "properties": {
              "filePath": {
                "description": "An optional file path to access a .pen file.",
                "type": "string"
              },
              "format": {
                "description": "Output format (default: html-tailwind)",
                "enum": [
                  "html-tailwind",
                  "html-css"
                ],
                "type": "string"
              },
              "includeHtmlScaffold": {
                "description": "Include a full HTML document scaffold (default: true)",
                "type": "boolean"
              },
              "includeLayerIds": {
                "description": "Include layer IDs as data attributes (default: false)",
                "type": "boolean"
              },
              "includeLayerNames": {
                "description": "Include layer names as data attributes (default: true)",
                "type": "boolean"
              },
              "nodeIds": {
                "description": "Array of node IDs to export",
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              "outputPath": {
                "description": "Path to write the exported HTML file",
                "type": "string"
              }
            },
            "required": [
              "filePath",
              "nodeIds",
              "outputPath"
            ],
            "type": "object"
          }
        },
        {
          "tool_name": "pencil__batch_design",
          "description": "Use get_editor_state if you don't have batch_design documentation",
          "score": 1.0834163427352905,
          "input_schema": {
            "properties": {
              "filePath": {
                "description": "An optional file path to access a .pen file.",
                "type": "string"
              },
              "input": {
                "type": "string"
              }
            },
            "required": [
              "filePath",
              "input"
            ],
            "type": "object"
          }
        }
      ]
    },
    {
      "server": "zai-mcp-server",
      "tools": [
        {
          "tool_name": "zai-mcp-server__ui_to_artifact",
          "description": "Convert UI screenshots into various artifacts: code, prompts, design specifications, or descriptions.\n\nUse this tool ONLY when the user wants to:\n- Generate frontend code from UI design (output_type='code')\n- Create AI prompts for UI generation (output_type='prompt')\n- Extract design specifications (output_type='spec')\n- Get natural language description of the UI (output_type='description')\n\nDo NOT use for: screenshots containing text/code to extract, error messages, diagrams, or data visualizations.",
          "score": 1.6470533609390259,
          "input_schema": {
            "type": "object",
            "properties": {
              "image_source": {
                "type": "string",
                "description": "Local file path or remote URL to the image"
              },
              "output_type": {
                "type": "string",
                "enum": [
                  "code",
                  "prompt",
                  "spec",
                  "description"
                ],
                "description": "Type of output to generate. Options: 'code' (generate frontend code), 'prompt' (generate AI prompt for recreating this UI), 'spec' (generate design specification document), 'description' (natural language description of the UI)."
              },
              "prompt": {
                "type": "string",
                "description": "Detailed instructions describing what to generate from this UI image. Should clearly state the desired output and any specific requirements."
              }
            },
            "required": [
              "image_source",
              "output_type",
              "prompt"
            ],
            "additionalProperties": false,
            "$schema": "http://json-schema.org/draft-07/schema#"
          }
        }
      ]
    }
  ],
  "total_hidden_tools": 19,
  "status": "ready",
  "note": null
}

